#!/usr/bin/env bash
set -e
echo ">> Updating /root/hudson ..."
mkdir -p /root/hudson
cat > /root/hudson/site.gz.b64 <<'B64EOF'

B64EOF
base64 -d /root/hudson/site.gz.b64 | gunzip > /root/hudson/index.html
rm -f /root/hudson/site.gz.b64
GOT=$(sha256sum /root/hudson/index.html | awk '{print $1}')
WANT=64be26f4742ebbd486f67314a42e09b14cb0eb152dac69fa4a036558b58c0f8d
echo ">> page sha256: $GOT"
if [ "$GOT" != "$WANT" ]; then echo "!! CHECKSUM MISMATCH — stopping"; exit 1; fi
echo ">> checksum OK"
cat > /root/hudson/docker-compose.yml <<'YMLEOF'
services:
  hudson:
    image: nginx:alpine
    container_name: hudson-site
    restart: always
    volumes:
      - ./index.html:/usr/share/nginx/html/index.html:ro
    networks:
      - root_default
    labels:
      - "traefik.enable=true"
      - "traefik.http.routers.hudson.rule=Host(`hudson.serenemedspas.com`)"
      - "traefik.http.routers.hudson.entrypoints=web,websecure"
      - "traefik.http.routers.hudson.tls=true"
      - "traefik.http.routers.hudson.tls.certresolver=mytlschallenge"
      - "traefik.http.services.hudson.loadbalancer.server.port=80"
networks:
  root_default:
    external: true
YMLEOF
cd /root/hudson && docker compose up -d
echo ">> Reloading page (no restart needed — nginx serves the updated file live)."
docker exec hudson-site nginx -s reload 2>/dev/null || true
echo ">> Done. hudson-site is serving the updated page. Refresh https://hudson.serenemedspas.com"
